//go:build ignore

// Copy into upstream converter/musicxml and run TestCodexMusicXMLUnpitched.
package musicxml
import("encoding/json";"fmt";"math/rand";"os";"path/filepath";"testing";"github.com/shibukawa/tinygodriver/encoding/xmlro";"github.com/shibukawa/bdf/converter/internal/music")
func TestCodexMusicXMLUnpitched(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};r:=rand.New(rand.NewSource(169241));steps:=[]string{"C","D","E","F","G","A","B","c","?",""};octaves:=[]string{"","0","4","5","9","-1","10","-2","3.5","invalid"};ids:=[]string{"","I1","I2","I3","missing"};out:=[]any{}
 for i:=0;i<8000;i++ {id:=ids[r.Intn(len(ids))];src:=fmt.Sprintf(`<note><unpitched><display-step>%s</display-step><display-octave>%s</display-octave></unpitched><instrument id="%s"/><tie type="%s"/></note>`,steps[r.Intn(len(steps))],octaves[r.Intn(len(octaves))],id,[]string{"start","stop","none"}[r.Intn(3)]);d:=newXMLReader([]byte(src));for{k,e:=d.Next();if e!=nil{t.Fatal(e)};if k==xmlro.StartElement{break}};n,e:=readNode(d);if e!=nil{t.Fatal(e)};reader:=newReader();p:=newPart("P1","");inst:=[]any{};for j:=0;j<r.Intn(4);j++{in:=&instrument{id:ids[r.Intn(len(ids))],unpitched:r.Intn(129)-1};p.instruments=append(p.instruments,in);if in.id!=""{p.instByID[in.id]=in};inst=append(inst,[]any{in.id,in.unpitched})};st:=&mstate{pm:&music.PartMeasure{},play:&playMeasure{},tuplets:map[int]*tupletState{}};reader.note(p,st,n);v:=st.pm.Events[0].Notes[0];play:=st.play.notes[0];out=append(out,map[string]any{"input":[]byte(src),"instruments":inst,"want":[]any{v.Pitch.Step,v.Pitch.Alter,v.Pitch.Octave,play.key,int(v.Accidental),v.TieStart,v.TieStop,play.tieStart,play.tieStop,p.unpitched,v.SoundingMIDI==nil}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/musicxml/unpitched.json"),b,0644);e!=nil{t.Fatal(e)}}
